{
  "recommendation": "EcoCard",
  "reason": "It is the only currently documented personal card with a specific new-customer sign-up bonus: 2,000 sustainability points, worth $20 when redeemed as a statement credit or checking-account credit.",
  "offer_details": {
    "qualifying_spend": "$5,000 in eligible purchases within the first month",
    "offer_window": "August 1, 2025 through December 15, 2025",
    "bonus_posting": "After the qualifying period closes and transactions have cleared",
    "exclusions": [
      "Returns, chargebacks, and disputed transactions reduce qualifying spend",
      "Balance transfers, cash equivalents, and fees do not count"
    ],
    "annual_fee": "$50",
    "minimum_credit_score": "No credit score requirement listed"
  },
  "other_promotions_reviewed": [
    {
      "card": "Silver Zoom Card",
      "promotion": "3x cash back for nine months from account opening",
      "limitation": "It is a business card, and the documentation does not specify a sign-up bonus or fixed bonus value."
    },
    {
      "card": "Business Silver Rewards Card",
      "promotion": "2x cash back for six months",
      "limitation": "It is a business card, and the documented promotion ended November 14, 2025; no fixed sign-up bonus is specified."
    }
  ],
  "note": "Because your top priority is a defined sign-up bonus in points or cash value, the EcoCard is the strongest documented match. If you are considering business cards or expect very high spending over several months, the Silver Zoom promotion may be worth comparing separately."
